import {readFileSync} from "node:fs";
import assert from "node:assert/strict";
const cfg=JSON.parse(readFileSync("build/server/wrangler.json","utf8"));
assert.equal(cfg.name,"hummin-web-production");
assert.equal(cfg.vars.CONTACT_ENABLED,"true");
assert.equal(cfg.vars.BOOKING_ENABLED,"true");
assert.equal(cfg.vars.ADMIN_AUTH_ENABLED,"true");
assert.equal(cfg.d1_databases?.[0]?.database_id,"acd04e85-a433-463b-865f-a01f8aac3e27");
assert.ok(cfg.main,"Bundled server entry required");
assert.ok(!JSON.stringify(cfg).includes("a6fb62df-824e-4231-8630-34ce1e6c27f4"),"Preview DB must not appear");
assert.ok(!JSON.stringify(cfg).includes("routes"),"No public routes during staging");
console.log("PASS production Worker bundle and binding isolation");
